-- varios sentidos explícitos con | o ;, el español conserva la misma amplitud.
-- Política: insert-only + ON CONFLICT DO NOTHING.
-- Reversión exacta:
-- DELETE FROM public.biblical_hebrew_spanish_glosses
-- WHERE provenance->>'batch_id' = 'fase_h_es_verbs_plain_editorial_003_20260820';

