 jsonb_build_object('phase','FASE_H_BLOQUE_3','batch_id','fase_h_es_verbs_plain_editorial_003_20260820','source','STEPBible/TAHOT source_gloss en','source_license','CC BY 4.0','translation_layer','VIDA editorial Spanish','translation_basis','exact approved English source_gloss + verb POS; explicit source ambiguity preserved in Spanish','context_used_as_meaning',false,'rv1909_used_as_meaning',false,'hebrew_lemma_used_to_infer_meaning',false,'strong_number',strong_number)
from eligible
